import{_ as p,c as o,a,b as e,d as s,e as c,w as i,r as l,o as u}from"./app-BCUmHMw7.js";const r={};function d(k,n){const t=l("RouteLink");return u(),o("div",null,[n[5]||(n[5]=a(`<h1 id="kafka" tabindex="-1"><a class="header-anchor" href="#kafka"><span>Kafka</span></a></h1><p>FluxaORM provides first-class support for Apache Kafka as a data pool type. Under the hood it uses <a href="https://github.com/twmb/franz-go" target="_blank" rel="noopener noreferrer">franz-go</a>, a high-performance pure-Go Kafka client.</p><p>A Kafka pool represents a connection to a set of brokers and can contain <strong>multiple consumer groups</strong>, each with its own set of topics and configuration.</p><h2 id="pool-registration" tabindex="-1"><a class="header-anchor" href="#pool-registration"><span>Pool Registration</span></a></h2><p>Register a Kafka pool using the <code>RegisterKafka</code> method:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">import</span> <span class="token string">&quot;github.com/latolukasz/fluxaorm/v2&quot;</span></span>
<span class="line"></span>
<span class="line">registry <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewRegistry</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Kafka pool named &quot;events&quot;:</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaPoolOptions<span class="token punctuation">{</span></span>
<span class="line">    ClientID<span class="token punctuation">:</span> <span class="token string">&quot;my-service&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Pool with multiple brokers:</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;localhost:9093&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaPoolOptions<span class="token punctuation">{</span></span>
<span class="line">    ClientID<span class="token punctuation">:</span> <span class="token string">&quot;my-service&quot;</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Pool with no options (producer-only):</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="consumer-group-registration" tabindex="-1"><a class="header-anchor" href="#consumer-group-registration"><span>Consumer Group Registration</span></a></h2><p>Consumer groups are registered separately using the <code>RegisterKafkaConsumerGroup</code> method and the <code>KafkaConsumerGroupBuilder</code> fluent API:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token comment">// Register a single consumer group:</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaConsumerGroup</span><span class="token punctuation">(</span></span>
<span class="line">    fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;payments&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Register multiple consumer groups:</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaConsumerGroup</span><span class="token punctuation">(</span></span>
<span class="line">    fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;order-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaConsumerGroup</span><span class="token punctuation">(</span></span>
<span class="line">    fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;payment-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;payments&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Consumer group with all options:</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaConsumerGroup</span><span class="token punctuation">(</span></span>
<span class="line">    fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;payments&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">SessionTimeout</span><span class="token punctuation">(</span><span class="token number">30</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">RebalanceTimeout</span><span class="token punctuation">(</span><span class="token number">60</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">FetchMaxBytes</span><span class="token punctuation">(</span><span class="token number">10485760</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">AutoCommitInterval</span><span class="token punctuation">(</span><span class="token number">5</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Equivalent YAML configuration:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">events</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> localhost<span class="token punctuation">:</span><span class="token number">9092</span></span>
<span class="line">      <span class="token punctuation">-</span> localhost<span class="token punctuation">:</span><span class="token number">9093</span></span>
<span class="line">    <span class="token key atrule">clientID</span><span class="token punctuation">:</span> my<span class="token punctuation">-</span>service</span>
<span class="line">    <span class="token key atrule">consumerGroups</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> order<span class="token punctuation">-</span>group</span>
<span class="line">        <span class="token key atrule">topics</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token punctuation">-</span> orders</span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> payment<span class="token punctuation">-</span>group</span>
<span class="line">        <span class="token key atrule">topics</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token punctuation">-</span> payments</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="kafkapooloptions" tabindex="-1"><a class="header-anchor" href="#kafkapooloptions"><span>KafkaPoolOptions</span></a></h2><p>The <code>KafkaPoolOptions</code> struct configures pool-level settings shared by all consumer groups:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> KafkaPoolOptions <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    ClientID              <span class="token builtin">string</span></span>
<span class="line">    RequiredAcks          <span class="token builtin">int</span></span>
<span class="line">    ProducerLinger        time<span class="token punctuation">.</span>Duration</span>
<span class="line">    MaxBufferedRecords    <span class="token builtin">int</span></span>
<span class="line">    SASL                  <span class="token operator">*</span>KafkaSASLConfig</span>
<span class="line">    IgnoredTopics         <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span></span>
<span class="line">    IgnoredConsumerGroups <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>ClientID</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Client identifier sent to the broker</td></tr><tr><td><code>RequiredAcks</code></td><td><code>int</code></td><td><code>-1</code></td><td>Broker acknowledgment level: <code>0</code> = none, <code>1</code> = leader only, <code>-1</code> = all in-sync replicas</td></tr><tr><td><code>ProducerLinger</code></td><td><code>time.Duration</code></td><td><code>0</code></td><td>How long to wait before flushing a produce batch</td></tr><tr><td><code>MaxBufferedRecords</code></td><td><code>int</code></td><td><code>0</code></td><td>Maximum number of records buffered in the producer</td></tr><tr><td><code>SASL</code></td><td><code>*KafkaSASLConfig</code></td><td><code>nil</code></td><td>SASL authentication configuration</td></tr><tr><td><code>IgnoredTopics</code></td><td><code>[]string</code></td><td><code>nil</code></td><td>Topics to exclude from schema management (see <a href="#topic-registration">Topic Registration</a>)</td></tr><tr><td><code>IgnoredConsumerGroups</code></td><td><code>[]string</code></td><td><code>nil</code></td><td>Consumer groups to exclude from deletion by <code>GetKafkaAlters()</code> (see <a href="#consumer-group-management">Consumer Group Management</a>)</td></tr></tbody></table><h2 id="kafkaconsumergroupbuilder" tabindex="-1"><a class="header-anchor" href="#kafkaconsumergroupbuilder"><span>KafkaConsumerGroupBuilder</span></a></h2><p>Consumer groups are configured using the <code>KafkaConsumerGroupBuilder</code> fluent API. Create a new builder with <code>NewKafkaConsumerGroup(name, poolCode)</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">cg <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;payments&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">SessionTimeout</span><span class="token punctuation">(</span><span class="token number">30</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">FetchMaxBytes</span><span class="token punctuation">(</span><span class="token number">10485760</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>All builder methods return <code>*KafkaConsumerGroupBuilder</code> for fluent chaining:</p><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>Topics(topics ...string)</code></td><td>Topics to consume from (<strong>required</strong>)</td></tr><tr><td><code>SessionTimeout(d time.Duration)</code></td><td>Consumer group session timeout</td></tr><tr><td><code>RebalanceTimeout(d time.Duration)</code></td><td>Consumer group rebalance timeout</td></tr><tr><td><code>FetchMaxBytes(n int32)</code></td><td>Maximum bytes per fetch response</td></tr><tr><td><code>AutoCommitInterval(d time.Duration)</code></td><td>Interval for automatic offset commits; <code>0</code> means manual commit</td></tr></tbody></table><h2 id="config-structs" tabindex="-1"><a class="header-anchor" href="#config-structs"><span>Config Structs</span></a></h2><p>When loading configuration from a file, FluxaORM uses the <code>ConfigKafka</code>, <code>ConfigKafkaConsumerGroup</code>, and <code>ConfigKafkaTopic</code> structs:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> ConfigKafkaConsumerGroup <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Name                 <span class="token builtin">string</span>   <span class="token string">\`yaml:&quot;name&quot;\`</span></span>
<span class="line">    Topics               <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span> <span class="token string">\`yaml:&quot;topics&quot;\`</span></span>
<span class="line">    SessionTimeoutMs     <span class="token builtin">int</span>      <span class="token string">\`yaml:&quot;sessionTimeoutMs&quot;\`</span></span>
<span class="line">    RebalanceTimeoutMs   <span class="token builtin">int</span>      <span class="token string">\`yaml:&quot;rebalanceTimeoutMs&quot;\`</span></span>
<span class="line">    FetchMaxBytes        <span class="token builtin">int</span>      <span class="token string">\`yaml:&quot;fetchMaxBytes&quot;\`</span></span>
<span class="line">    AutoCommitIntervalMs <span class="token builtin">int</span>      <span class="token string">\`yaml:&quot;autoCommitIntervalMs&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> ConfigKafkaTopic <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Name              <span class="token builtin">string</span>            <span class="token string">\`yaml:&quot;name&quot;\`</span></span>
<span class="line">    Partitions        <span class="token builtin">int32</span>             <span class="token string">\`yaml:&quot;partitions&quot;\`</span></span>
<span class="line">    ReplicationFactor <span class="token builtin">int16</span>             <span class="token string">\`yaml:&quot;replicationFactor&quot;\`</span></span>
<span class="line">    Configs           <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token builtin">string</span> <span class="token string">\`yaml:&quot;configs&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> ConfigKafka <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Code                  <span class="token builtin">string</span>                     <span class="token string">\`yaml:&quot;code&quot;\`</span></span>
<span class="line">    Brokers               <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span>                   <span class="token string">\`yaml:&quot;brokers&quot;\`</span></span>
<span class="line">    ClientID              <span class="token builtin">string</span>                     <span class="token string">\`yaml:&quot;clientID&quot;\`</span></span>
<span class="line">    RequiredAcks          <span class="token builtin">int</span>                        <span class="token string">\`yaml:&quot;requiredAcks&quot;\`</span></span>
<span class="line">    ProducerLingerMs      <span class="token builtin">int</span>                        <span class="token string">\`yaml:&quot;producerLingerMs&quot;\`</span></span>
<span class="line">    MaxBufferedRecords    <span class="token builtin">int</span>                        <span class="token string">\`yaml:&quot;maxBufferedRecords&quot;\`</span></span>
<span class="line">    SASLMechanism         <span class="token builtin">string</span>                     <span class="token string">\`yaml:&quot;saslMechanism&quot;\`</span></span>
<span class="line">    SASLUser              <span class="token builtin">string</span>                     <span class="token string">\`yaml:&quot;saslUser&quot;\`</span></span>
<span class="line">    SASLPassword          <span class="token builtin">string</span>                     <span class="token string">\`yaml:&quot;saslPassword&quot;\`</span></span>
<span class="line">    ConsumerGroups        <span class="token punctuation">[</span><span class="token punctuation">]</span>ConfigKafkaConsumerGroup <span class="token string">\`yaml:&quot;consumerGroups&quot;\`</span></span>
<span class="line">    IgnoredTopics         <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span>                   <span class="token string">\`yaml:&quot;ignoredTopics&quot;\`</span></span>
<span class="line">    IgnoredConsumerGroups <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span>                   <span class="token string">\`yaml:&quot;ignoredConsumerGroups&quot;\`</span></span>
<span class="line">    Topics                <span class="token punctuation">[</span><span class="token punctuation">]</span>ConfigKafkaTopic         <span class="token string">\`yaml:&quot;topics&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="engine-accessor" tabindex="-1"><a class="header-anchor" href="#engine-accessor"><span>Engine Accessor</span></a></h2><p>Once the engine is created, access a Kafka pool via:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">pool <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>This returns a <code>Kafka</code> interface representing the pool. You can produce records directly via the pool, and obtain consumer groups from the pool for consuming records.</p><h2 id="consumer-groups" tabindex="-1"><a class="header-anchor" href="#consumer-groups"><span>Consumer Groups</span></a></h2><p>Each Kafka pool can have one or more consumer groups. Use the pool-level methods to access them:</p><h3 id="consumergroup" tabindex="-1"><a class="header-anchor" href="#consumergroup"><span>ConsumerGroup</span></a></h3><p><code>ConsumerGroup</code> returns a <code>KafkaConsumerGroup</code> and an error. Each call creates a <strong>new <code>kgo.Client</code></strong> connected to the brokers — it is a factory method, not a lookup. The caller is responsible for calling <code>Close()</code> on the returned consumer group when done:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">cg<span class="token punctuation">,</span> err <span class="token operator">:=</span> pool<span class="token punctuation">.</span><span class="token function">ConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// name not registered or connection failed</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">defer</span> cg<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="mustconsumergroup" tabindex="-1"><a class="header-anchor" href="#mustconsumergroup"><span>MustConsumerGroup</span></a></h3><p><code>MustConsumerGroup</code> returns a <code>KafkaConsumerGroup</code> for the given name and panics if the group is not registered or if the connection fails. Use this when you are certain the group was registered and you want to fail fast on errors:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">cg <span class="token operator">:=</span> pool<span class="token punctuation">.</span><span class="token function">MustConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> cg<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="consumergroupnames" tabindex="-1"><a class="header-anchor" href="#consumergroupnames"><span>ConsumerGroupNames</span></a></h3><p><code>ConsumerGroupNames</code> returns the list of registered consumer group names in the pool:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> name <span class="token operator">:=</span> <span class="token keyword">range</span> pool<span class="token punctuation">.</span><span class="token function">ConsumerGroupNames</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>name<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="kafka-pool-interface" tabindex="-1"><a class="header-anchor" href="#kafka-pool-interface"><span>Kafka (Pool) Interface</span></a></h3><p>The <code>Kafka</code> interface exposes pool-level methods:</p><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>GetCode() string</code></td><td>Returns the pool code (e.g. <code>&quot;events&quot;</code>)</td></tr><tr><td><code>GetBrokers() []string</code></td><td>Returns the list of broker addresses</td></tr><tr><td><code>GetPoolOptions() *KafkaPoolOptions</code></td><td>Returns the pool-level options</td></tr><tr><td><code>ProduceSync(ctx Context, records ...*KafkaRecord) error</code></td><td>Produces records synchronously and blocks until acknowledged</td></tr><tr><td><code>Produce(ctx Context, record *KafkaRecord, callback func(*KafkaRecord, error))</code></td><td>Produces a record asynchronously with an optional callback</td></tr><tr><td><code>ConsumerGroup(name string) (KafkaConsumerGroup, error)</code></td><td>Creates a new consumer group client by name; returns error if not registered or connection fails</td></tr><tr><td><code>MustConsumerGroup(name string) KafkaConsumerGroup</code></td><td>Creates a new consumer group client by name; panics if not registered or connection fails</td></tr><tr><td><code>ConsumerGroupNames() []string</code></td><td>Returns the list of registered consumer group names</td></tr><tr><td><code>Close()</code></td><td>Closes the pool-level producer client; consumer groups must be closed individually</td></tr></tbody></table><h3 id="kafkaconsumergroup-interface" tabindex="-1"><a class="header-anchor" href="#kafkaconsumergroup-interface"><span>KafkaConsumerGroup Interface</span></a></h3><p>The <code>KafkaConsumerGroup</code> interface exposes per-group methods:</p><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>GetName() string</code></td><td>Returns the consumer group name</td></tr><tr><td><code>GetSettings() *KafkaConsumerGroupSettings</code></td><td>Returns the consumer group settings</td></tr><tr><td><code>GetKgoClient() *kgo.Client</code></td><td>Returns the underlying franz-go client</td></tr><tr><td><code>PollFetches(ctx Context) KafkaFetches</code></td><td>Polls for new records</td></tr><tr><td><code>CommitUncommittedOffsets(ctx Context) error</code></td><td>Commits offsets for consumed records</td></tr><tr><td><code>Close()</code></td><td>Closes this consumer group&#39;s client</td></tr></tbody></table><h2 id="kafkarecord" tabindex="-1"><a class="header-anchor" href="#kafkarecord"><span>KafkaRecord</span></a></h2><p><code>KafkaRecord</code> represents a single Kafka record (message):</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> KafkaRecord <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Topic     <span class="token builtin">string</span></span>
<span class="line">    Key       <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span></span>
<span class="line">    Value     <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span></span>
<span class="line">    Headers   <span class="token punctuation">[</span><span class="token punctuation">]</span>KafkaRecordHeader</span>
<span class="line">    Partition <span class="token builtin">int32</span></span>
<span class="line">    Offset    <span class="token builtin">int64</span></span>
<span class="line">    Timestamp time<span class="token punctuation">.</span>Time</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="kafkarecordheader" tabindex="-1"><a class="header-anchor" href="#kafkarecordheader"><span>KafkaRecordHeader</span></a></h2><p><code>KafkaRecordHeader</code> represents a key-value header attached to a record:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> KafkaRecordHeader <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Key   <span class="token builtin">string</span></span>
<span class="line">    Value <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">byte</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="kafkafetches" tabindex="-1"><a class="header-anchor" href="#kafkafetches"><span>KafkaFetches</span></a></h2><p><code>KafkaFetches</code> is returned by <code>PollFetches</code> and provides helper methods for iterating over fetched records:</p><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>Records() []*KafkaRecord</code></td><td>Returns all records from the fetch as a flat slice</td></tr><tr><td><code>EachRecord(func(*KafkaRecord))</code></td><td>Iterates over each record, calling the provided function</td></tr><tr><td><code>EachError(func(string, int32, error))</code></td><td>Iterates over per-partition errors (topic, partition, error)</td></tr><tr><td><code>IsEmpty() bool</code></td><td>Returns <code>true</code> if the fetch contains no records</td></tr></tbody></table><h2 id="producing-records" tabindex="-1"><a class="header-anchor" href="#producing-records"><span>Producing Records</span></a></h2><p>All produce operations are performed through the pool directly. You do not need a consumer group to produce records.</p><h3 id="synchronous-produce" tabindex="-1"><a class="header-anchor" href="#synchronous-produce"><span>Synchronous Produce</span></a></h3><p><code>ProduceSync</code> sends one or more records to Kafka and blocks until the broker acknowledges them:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">pool <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">record <span class="token operator">:=</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaRecord<span class="token punctuation">{</span></span>
<span class="line">    Topic<span class="token punctuation">:</span> <span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    Key<span class="token punctuation">:</span>   <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">&quot;order-123&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Value<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;status&quot;:&quot;created&quot;}\`</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Headers<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>fluxaorm<span class="token punctuation">.</span>KafkaRecordHeader<span class="token punctuation">{</span></span>
<span class="line">        <span class="token punctuation">{</span>Key<span class="token punctuation">:</span> <span class="token string">&quot;source&quot;</span><span class="token punctuation">,</span> Value<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">&quot;api&quot;</span><span class="token punctuation">)</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">err <span class="token operator">:=</span> pool<span class="token punctuation">.</span><span class="token function">ProduceSync</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> record<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// handle error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="asynchronous-produce" tabindex="-1"><a class="header-anchor" href="#asynchronous-produce"><span>Asynchronous Produce</span></a></h3><p><code>Produce</code> sends a record asynchronously. The call returns immediately and the record is buffered for delivery. An optional callback is invoked when the broker acknowledges or rejects the record:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">pool <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">record <span class="token operator">:=</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaRecord<span class="token punctuation">{</span></span>
<span class="line">    Topic<span class="token punctuation">:</span> <span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    Key<span class="token punctuation">:</span>   <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">&quot;order-456&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    Value<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;status&quot;:&quot;shipped&quot;}\`</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">pool<span class="token punctuation">.</span><span class="token function">Produce</span><span class="token punctuation">(</span>ctx<span class="token punctuation">,</span> record<span class="token punctuation">,</span> <span class="token keyword">func</span><span class="token punctuation">(</span>r <span class="token operator">*</span>fluxaorm<span class="token punctuation">.</span>KafkaRecord<span class="token punctuation">,</span> err <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        log<span class="token punctuation">.</span><span class="token function">Printf</span><span class="token punctuation">(</span><span class="token string">&quot;produce failed: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="consuming-records" tabindex="-1"><a class="header-anchor" href="#consuming-records"><span>Consuming Records</span></a></h2><h3 id="pollfetches" tabindex="-1"><a class="header-anchor" href="#pollfetches"><span>PollFetches</span></a></h3><p><code>PollFetches</code> polls the broker for new records. It returns a <code>KafkaFetches</code> value:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">pool <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">Kafka</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">)</span></span>
<span class="line">cg <span class="token operator">:=</span> pool<span class="token punctuation">.</span><span class="token function">MustConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> cg<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">fetches <span class="token operator">:=</span> cg<span class="token punctuation">.</span><span class="token function">PollFetches</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> fetches<span class="token punctuation">.</span><span class="token function">IsEmpty</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">fetches<span class="token punctuation">.</span><span class="token function">EachError</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>topic <span class="token builtin">string</span><span class="token punctuation">,</span> partition <span class="token builtin">int32</span><span class="token punctuation">,</span> err <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    log<span class="token punctuation">.</span><span class="token function">Printf</span><span class="token punctuation">(</span><span class="token string">&quot;fetch error topic=%s partition=%d: %v&quot;</span><span class="token punctuation">,</span> topic<span class="token punctuation">,</span> partition<span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">fetches<span class="token punctuation">.</span><span class="token function">EachRecord</span><span class="token punctuation">(</span><span class="token keyword">func</span><span class="token punctuation">(</span>record <span class="token operator">*</span>fluxaorm<span class="token punctuation">.</span>KafkaRecord<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Printf</span><span class="token punctuation">(</span><span class="token string">&quot;topic=%s key=%s value=%s\\n&quot;</span><span class="token punctuation">,</span> record<span class="token punctuation">.</span>Topic<span class="token punctuation">,</span> record<span class="token punctuation">.</span>Key<span class="token punctuation">,</span> record<span class="token punctuation">.</span>Value<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="commituncommittedoffsets" tabindex="-1"><a class="header-anchor" href="#commituncommittedoffsets"><span>CommitUncommittedOffsets</span></a></h3><p>After processing records, commit the offsets so they are not re-delivered:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">err <span class="token operator">:=</span> cg<span class="token punctuation">.</span><span class="token function">CommitUncommittedOffsets</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// handle error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>When <code>AutoCommitInterval</code> is set to <code>0</code> (the default), you must call <code>CommitUncommittedOffsets</code> manually after processing each batch. Set a positive <code>AutoCommitInterval</code> via the <code>KafkaConsumerGroupBuilder</code> to enable automatic periodic commits.</p></div><h2 id="advanced-usage" tabindex="-1"><a class="header-anchor" href="#advanced-usage"><span>Advanced Usage</span></a></h2><p>If you need direct access to the underlying <code>*kgo.Client</code> from franz-go, use <code>GetKgoClient</code> on a consumer group:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">cg <span class="token operator">:=</span> pool<span class="token punctuation">.</span><span class="token function">MustConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> cg<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">client <span class="token operator">:=</span> cg<span class="token punctuation">.</span><span class="token function">GetKgoClient</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// use the franz-go client directly for advanced operations</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="sasl-authentication" tabindex="-1"><a class="header-anchor" href="#sasl-authentication"><span>SASL Authentication</span></a></h2><p>To connect to a Kafka cluster that requires SASL authentication, configure the <code>SASL</code> field in <code>KafkaPoolOptions</code>. SASL is a pool-level setting shared by all consumer groups:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;kafka-broker:9093&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;secure-events&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaPoolOptions<span class="token punctuation">{</span></span>
<span class="line">    ClientID<span class="token punctuation">:</span> <span class="token string">&quot;my-service&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    SASL<span class="token punctuation">:</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaSASLConfig<span class="token punctuation">{</span></span>
<span class="line">        Mechanism<span class="token punctuation">:</span> <span class="token string">&quot;SCRAM-SHA-256&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        User<span class="token punctuation">:</span>      <span class="token string">&quot;kafka-user&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        Password<span class="token punctuation">:</span>  <span class="token string">&quot;kafka-password&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaConsumerGroup</span><span class="token punctuation">(</span></span>
<span class="line">    fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;secure-events&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>KafkaSASLConfig</code> supports the following mechanisms:</p><table><thead><tr><th>Mechanism</th><th>Description</th></tr></thead><tbody><tr><td><code>PLAIN</code></td><td>Simple username/password authentication (not recommended for production without TLS)</td></tr><tr><td><code>SCRAM-SHA-256</code></td><td>Challenge-response authentication using SHA-256</td></tr><tr><td><code>SCRAM-SHA-512</code></td><td>Challenge-response authentication using SHA-512</td></tr></tbody></table><p>Equivalent YAML:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">secure-events</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> kafka<span class="token punctuation">-</span>broker<span class="token punctuation">:</span><span class="token number">9093</span></span>
<span class="line">    <span class="token key atrule">clientID</span><span class="token punctuation">:</span> my<span class="token punctuation">-</span>service</span>
<span class="line">    <span class="token key atrule">saslMechanism</span><span class="token punctuation">:</span> SCRAM<span class="token punctuation">-</span>SHA<span class="token punctuation">-</span><span class="token number">256</span></span>
<span class="line">    <span class="token key atrule">saslUser</span><span class="token punctuation">:</span> kafka<span class="token punctuation">-</span>user</span>
<span class="line">    <span class="token key atrule">saslPassword</span><span class="token punctuation">:</span> kafka<span class="token punctuation">-</span>password</span>
<span class="line">    <span class="token key atrule">consumerGroups</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> my<span class="token punctuation">-</span>group</span>
<span class="line">        <span class="token key atrule">topics</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token punctuation">-</span> orders</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="topic-registration" tabindex="-1"><a class="header-anchor" href="#topic-registration"><span>Topic Registration</span></a></h2>`,80)),e("p",null,[n[1]||(n[1]=s("FluxaORM provides schema management for Kafka topics, similar to the ",-1)),c(t,{to:"/guide/clickhouse_schema.html"},{default:i(()=>n[0]||(n[0]=[s("ClickHouse schema management",-1)])),_:1,__:[0]}),n[2]||(n[2]=s(" feature. Define your Kafka topics using a fluent builder API, register them with the registry, and use ",-1)),n[3]||(n[3]=e("code",null,"GetKafkaAlters()",-1)),n[4]||(n[4]=s(" to compare them with the broker state and apply changes.",-1))]),n[6]||(n[6]=a(`<h3 id="defining-a-kafka-topic" tabindex="-1"><a class="header-anchor" href="#defining-a-kafka-topic"><span>Defining a Kafka Topic</span></a></h3><p>Use <code>NewKafkaTopic()</code> to create a topic definition with a fluent builder:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">import</span> fluxaorm <span class="token string">&quot;github.com/latolukasz/fluxaorm/v2&quot;</span></span>
<span class="line"></span>
<span class="line">topic <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaTopic</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">Partitions</span><span class="token punctuation">(</span><span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">ReplicationFactor</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">RetentionMs</span><span class="token punctuation">(</span><span class="token number">86400000</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">CleanupPolicy</span><span class="token punctuation">(</span><span class="token string">&quot;delete&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">    <span class="token function">MinInsyncReplicas</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="registering-topics" tabindex="-1"><a class="header-anchor" href="#registering-topics"><span>Registering Topics</span></a></h3><p>Register Kafka topic definitions with the registry before calling <code>Validate()</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">registry <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewRegistry</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaTopic</span><span class="token punctuation">(</span></span>
<span class="line">    fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaTopic</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">Partitions</span><span class="token punctuation">(</span><span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">ReplicationFactor</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">RetentionMs</span><span class="token punctuation">(</span><span class="token number">86400000</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">CleanupPolicy</span><span class="token punctuation">(</span><span class="token string">&quot;delete&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">MinInsyncReplicas</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaTopic</span><span class="token punctuation">(</span></span>
<span class="line">    fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaTopic</span><span class="token punctuation">(</span><span class="token string">&quot;payments&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">Partitions</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">ReplicationFactor</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">RetentionBytes</span><span class="token punctuation">(</span><span class="token number">1073741824</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">        <span class="token function">MaxMessageBytes</span><span class="token punctuation">(</span><span class="token number">1048576</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">engine<span class="token punctuation">,</span> err <span class="token operator">:=</span> registry<span class="token punctuation">.</span><span class="token function">Validate</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="builder-api-reference" tabindex="-1"><a class="header-anchor" href="#builder-api-reference"><span>Builder API Reference</span></a></h3><p>All builder methods return <code>*KafkaTopicBuilder</code> for fluent chaining:</p><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>Partitions(n int32)</code></td><td>Number of partitions for the topic</td></tr><tr><td><code>ReplicationFactor(n int16)</code></td><td>Replication factor for the topic</td></tr><tr><td><code>RetentionMs(ms int64)</code></td><td>Message retention time in milliseconds (<code>retention.ms</code>)</td></tr><tr><td><code>RetentionBytes(bytes int64)</code></td><td>Maximum retained bytes per partition (<code>retention.bytes</code>)</td></tr><tr><td><code>MaxMessageBytes(bytes int32)</code></td><td>Maximum message size in bytes (<code>max.message.bytes</code>)</td></tr><tr><td><code>CleanupPolicy(policy string)</code></td><td>Cleanup policy: <code>&quot;delete&quot;</code>, <code>&quot;compact&quot;</code>, or <code>&quot;delete,compact&quot;</code> (<code>cleanup.policy</code>)</td></tr><tr><td><code>MinInsyncReplicas(n int)</code></td><td>Minimum number of in-sync replicas (<code>min.insync.replicas</code>)</td></tr><tr><td><code>CompressionType(ct string)</code></td><td>Compression type: <code>&quot;none&quot;</code>, <code>&quot;gzip&quot;</code>, <code>&quot;snappy&quot;</code>, <code>&quot;lz4&quot;</code>, <code>&quot;zstd&quot;</code> (<code>compression.type</code>)</td></tr><tr><td><code>Config(key, value string)</code></td><td>Set any arbitrary topic configuration key-value pair</td></tr></tbody></table><p>The convenience methods (<code>RetentionMs</code>, <code>CleanupPolicy</code>, etc.) are shorthand for common <code>Config()</code> calls.</p><h3 id="getting-topic-alters" tabindex="-1"><a class="header-anchor" href="#getting-topic-alters"><span>Getting Topic Alters</span></a></h3><p>Use <code>GetKafkaAlters()</code> to compare registered topic definitions with the actual Kafka broker state and get the pending operations:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">ctx <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">NewContext</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">alters<span class="token punctuation">,</span> err <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">GetKafkaAlters</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">panic</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> alter <span class="token operator">:=</span> <span class="token keyword">range</span> alters <span class="token punctuation">{</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>alter<span class="token punctuation">.</span>Description<span class="token punctuation">)</span> <span class="token comment">// e.g. &quot;Create topic &#39;orders&#39; with 6 partitions&quot;</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>alter<span class="token punctuation">.</span>Pool<span class="token punctuation">)</span>        <span class="token comment">// e.g. &quot;default&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Each <code>fluxaorm.KafkaAlter</code> has the following fields:</p><table><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>Description</code></td><td><code>string</code></td><td>Human-readable description of the pending operation</td></tr><tr><td><code>Pool</code></td><td><code>string</code></td><td>The Kafka pool code this alter belongs to</td></tr></tbody></table><p>To execute all alters:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> alter <span class="token operator">:=</span> <span class="token keyword">range</span> alters <span class="token punctuation">{</span></span>
<span class="line">    err <span class="token operator">=</span> alter<span class="token punctuation">.</span><span class="token function">Exec</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">panic</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="what-gets-compared" tabindex="-1"><a class="header-anchor" href="#what-gets-compared"><span>What Gets Compared</span></a></h3><p><code>GetKafkaAlters()</code> generates the following types of operations:</p><table><thead><tr><th>Scenario</th><th>Operation</th></tr></thead><tbody><tr><td>Topic not on broker</td><td>Create topic with registered partitions, replication factor, and configs</td></tr><tr><td>Registered partitions &gt; current partitions</td><td>Increase partition count</td></tr><tr><td>Registered partitions &lt; current partitions</td><td>Warning (partitions cannot be decreased)</td></tr><tr><td>Replication factor differs</td><td>Warning (replication factor cannot be changed via admin API)</td></tr><tr><td>Topic config differs from registered values</td><td>Alter topic configuration</td></tr><tr><td>Topic on broker but not registered</td><td>Delete topic</td></tr><tr><td>Consumer group on broker but not registered</td><td>Delete consumer group</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Kafka does <strong>not</strong> support decreasing the number of partitions or changing the replication factor of an existing topic. If these differ, <code>GetKafkaAlters()</code> returns a warning description but no executable operation for these changes.</p></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>FluxaORM deletes all topics on the broker that are not registered, excluding internal topics (those starting with <code>__</code>) and topics listed in <code>IgnoredTopics</code>. See <a href="#ignored-topics">Ignored Topics</a> for how to protect topics from deletion.</p></div><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>FluxaORM also deletes all consumer groups on the broker that are not registered, excluding internal consumer groups (those starting with <code>__</code>) and consumer groups listed in <code>IgnoredConsumerGroups</code>. See <a href="#ignored-consumer-groups">Ignored Consumer Groups</a> for how to protect consumer groups from deletion.</p></div><h3 id="ignored-topics" tabindex="-1"><a class="header-anchor" href="#ignored-topics"><span>Ignored Topics</span></a></h3><p>By default, <code>GetKafkaAlters()</code> will attempt to delete topics on the broker that are not registered via <code>RegisterKafkaTopic()</code>. Internal Kafka topics (those starting with <code>__</code>, such as <code>__consumer_offsets</code>) are always excluded automatically.</p><p>To protect additional topics from deletion, list them in the <code>IgnoredTopics</code> field of <code>KafkaPoolOptions</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaPoolOptions<span class="token punctuation">{</span></span>
<span class="line">    IgnoredTopics<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;legacy-topic&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;external-service-topic&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Equivalent YAML:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">default</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> localhost<span class="token punctuation">:</span><span class="token number">9092</span></span>
<span class="line">    <span class="token key atrule">ignoredTopics</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> legacy<span class="token punctuation">-</span>topic</span>
<span class="line">      <span class="token punctuation">-</span> external<span class="token punctuation">-</span>service<span class="token punctuation">-</span>topic</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="consumer-group-management" tabindex="-1"><a class="header-anchor" href="#consumer-group-management"><span>Consumer Group Management</span></a></h3><p><code>GetKafkaAlters()</code> also manages consumer groups. It lists all consumer groups on the broker and generates <strong>DELETE</strong> alters for orphaned consumer groups -- those that exist on the broker but are not registered via <code>RegisterKafkaConsumerGroup()</code>.</p><p>The following consumer groups are excluded from deletion:</p><ul><li>Consumer groups that are registered in the application</li><li>Internal consumer groups (those starting with <code>__</code>)</li><li>Consumer groups listed in <code>IgnoredConsumerGroups</code></li></ul><h3 id="ignored-consumer-groups" tabindex="-1"><a class="header-anchor" href="#ignored-consumer-groups"><span>Ignored Consumer Groups</span></a></h3><p>By default, <code>GetKafkaAlters()</code> will attempt to delete consumer groups on the broker that are not registered. Internal consumer groups (those starting with <code>__</code>, such as <code>__consumer_offsets</code>) are always excluded automatically.</p><p>To protect additional consumer groups from deletion, list them in the <code>IgnoredConsumerGroups</code> field of <code>KafkaPoolOptions</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaPoolOptions<span class="token punctuation">{</span></span>
<span class="line">    IgnoredConsumerGroups<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;legacy-consumer&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;external-service-consumer&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Equivalent YAML:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">default</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> localhost<span class="token punctuation">:</span><span class="token number">9092</span></span>
<span class="line">    <span class="token key atrule">ignoredConsumerGroups</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> legacy<span class="token punctuation">-</span>consumer</span>
<span class="line">      <span class="token punctuation">-</span> external<span class="token punctuation">-</span>service<span class="token punctuation">-</span>consumer</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="backward-compatibility" tabindex="-1"><a class="header-anchor" href="#backward-compatibility"><span>Backward Compatibility</span></a></h3><p>Topic schema management is <strong>opt-in</strong> and fully backward compatible:</p><ul><li>If no topics are registered for a Kafka pool via <code>RegisterKafkaTopic()</code>, auto-topic creation remains enabled and <code>GetKafkaAlters()</code> will not manage topics for that pool.</li><li>Once you register at least one topic for a pool, <code>GetKafkaAlters()</code> takes over topic management for that pool, including deleting unregistered topics.</li><li>Pools with no registered topics will have all non-internal, non-ignored topics flagged for deletion by <code>GetKafkaAlters()</code>.</li></ul><h3 id="yaml-configuration" tabindex="-1"><a class="header-anchor" href="#yaml-configuration"><span>YAML Configuration</span></a></h3><p>Topics can also be defined in YAML configuration under the <code>topics</code> key within a Kafka pool:</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">default</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token key atrule">kafka</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token key atrule">brokers</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">&quot;localhost:9092&quot;</span></span>
<span class="line">    <span class="token key atrule">ignoredTopics</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">&quot;legacy-topic&quot;</span></span>
<span class="line">    <span class="token key atrule">ignoredConsumerGroups</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token string">&quot;legacy-consumer&quot;</span></span>
<span class="line">    <span class="token key atrule">topics</span><span class="token punctuation">:</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;orders&quot;</span></span>
<span class="line">        <span class="token key atrule">partitions</span><span class="token punctuation">:</span> <span class="token number">6</span></span>
<span class="line">        <span class="token key atrule">replicationFactor</span><span class="token punctuation">:</span> <span class="token number">3</span></span>
<span class="line">        <span class="token key atrule">configs</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">retention.ms</span><span class="token punctuation">:</span> <span class="token string">&quot;86400000&quot;</span></span>
<span class="line">          <span class="token key atrule">cleanup.policy</span><span class="token punctuation">:</span> <span class="token string">&quot;delete&quot;</span></span>
<span class="line">          <span class="token key atrule">min.insync.replicas</span><span class="token punctuation">:</span> <span class="token string">&quot;2&quot;</span></span>
<span class="line">      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;payments&quot;</span></span>
<span class="line">        <span class="token key atrule">partitions</span><span class="token punctuation">:</span> <span class="token number">3</span></span>
<span class="line">        <span class="token key atrule">replicationFactor</span><span class="token punctuation">:</span> <span class="token number">3</span></span>
<span class="line">        <span class="token key atrule">configs</span><span class="token punctuation">:</span></span>
<span class="line">          <span class="token key atrule">retention.bytes</span><span class="token punctuation">:</span> <span class="token string">&quot;1073741824&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="struct-configuration" tabindex="-1"><a class="header-anchor" href="#struct-configuration"><span>Struct Configuration</span></a></h3><p>Topics can be defined using the <code>ConfigKafkaTopic</code> struct within <code>ConfigKafka</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">config <span class="token operator">:=</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>Config<span class="token punctuation">{</span></span>
<span class="line">    KafkaPools<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>fluxaorm<span class="token punctuation">.</span>ConfigKafka<span class="token punctuation">{</span></span>
<span class="line">        <span class="token punctuation">{</span></span>
<span class="line">            Code<span class="token punctuation">:</span>                  <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span></span>
<span class="line">            Brokers<span class="token punctuation">:</span>               <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">            IgnoredTopics<span class="token punctuation">:</span>         <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;legacy-topic&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">            IgnoredConsumerGroups<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;legacy-consumer&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">            Topics<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>fluxaorm<span class="token punctuation">.</span>ConfigKafkaTopic<span class="token punctuation">{</span></span>
<span class="line">                <span class="token punctuation">{</span></span>
<span class="line">                    Name<span class="token punctuation">:</span>              <span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span></span>
<span class="line">                    Partitions<span class="token punctuation">:</span>        <span class="token number">6</span><span class="token punctuation">,</span></span>
<span class="line">                    ReplicationFactor<span class="token punctuation">:</span> <span class="token number">3</span><span class="token punctuation">,</span></span>
<span class="line">                    Configs<span class="token punctuation">:</span> <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span></span>
<span class="line">                        <span class="token string">&quot;retention.ms&quot;</span><span class="token punctuation">:</span>         <span class="token string">&quot;86400000&quot;</span><span class="token punctuation">,</span></span>
<span class="line">                        <span class="token string">&quot;cleanup.policy&quot;</span><span class="token punctuation">:</span>       <span class="token string">&quot;delete&quot;</span><span class="token punctuation">,</span></span>
<span class="line">                        <span class="token string">&quot;min.insync.replicas&quot;</span><span class="token punctuation">:</span>  <span class="token string">&quot;2&quot;</span><span class="token punctuation">,</span></span>
<span class="line">                    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">err <span class="token operator">:=</span> registry<span class="token punctuation">.</span><span class="token function">InitByConfig</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="full-example" tabindex="-1"><a class="header-anchor" href="#full-example"><span>Full Example</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">&quot;context&quot;</span></span>
<span class="line">    <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line">    <span class="token string">&quot;github.com/latolukasz/fluxaorm/v2&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    registry <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">NewRegistry</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>KafkaPoolOptions<span class="token punctuation">{</span></span>
<span class="line">        IgnoredTopics<span class="token punctuation">:</span>         <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;legacy-topic&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        IgnoredConsumerGroups<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;legacy-consumer&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Define consumer groups</span></span>
<span class="line">    registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaConsumerGroup</span><span class="token punctuation">(</span></span>
<span class="line">        fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;order-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line">    registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaConsumerGroup</span><span class="token punctuation">(</span></span>
<span class="line">        fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;payment-group&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Topics</span><span class="token punctuation">(</span><span class="token string">&quot;payments&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Define topics</span></span>
<span class="line">    registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaTopic</span><span class="token punctuation">(</span></span>
<span class="line">        fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaTopic</span><span class="token punctuation">(</span><span class="token string">&quot;orders&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">Partitions</span><span class="token punctuation">(</span><span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">ReplicationFactor</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">RetentionMs</span><span class="token punctuation">(</span><span class="token number">86400000</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">CleanupPolicy</span><span class="token punctuation">(</span><span class="token string">&quot;delete&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">MinInsyncReplicas</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    registry<span class="token punctuation">.</span><span class="token function">RegisterKafkaTopic</span><span class="token punctuation">(</span></span>
<span class="line">        fluxaorm<span class="token punctuation">.</span><span class="token function">NewKafkaTopic</span><span class="token punctuation">(</span><span class="token string">&quot;payments&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;default&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">Partitions</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">ReplicationFactor</span><span class="token punctuation">(</span><span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">RetentionBytes</span><span class="token punctuation">(</span><span class="token number">1073741824</span><span class="token punctuation">)</span><span class="token punctuation">.</span></span>
<span class="line">            <span class="token function">CompressionType</span><span class="token punctuation">(</span><span class="token string">&quot;snappy&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    engine<span class="token punctuation">,</span> err <span class="token operator">:=</span> registry<span class="token punctuation">.</span><span class="token function">Validate</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">panic</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    ctx <span class="token operator">:=</span> engine<span class="token punctuation">.</span><span class="token function">NewContext</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span><span class="token function">Background</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// Get and apply alters</span></span>
<span class="line">    alters<span class="token punctuation">,</span> err <span class="token operator">:=</span> fluxaorm<span class="token punctuation">.</span><span class="token function">GetKafkaAlters</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">panic</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token boolean">_</span><span class="token punctuation">,</span> alter <span class="token operator">:=</span> <span class="token keyword">range</span> alters <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>alter<span class="token punctuation">.</span>Description<span class="token punctuation">)</span></span>
<span class="line">        err <span class="token operator">=</span> alter<span class="token punctuation">.</span><span class="token function">Exec</span><span class="token punctuation">(</span>ctx<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">panic</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>Call <code>GetKafkaAlters()</code> alongside <code>GetAlters()</code>, <code>GetRedisSearchAlters()</code>, <code>GetClickhouseAlters()</code>, and <code>GetDebeziumAlters()</code> in your migration flow to keep all data stores in sync.</p></div><h2 id="async-flush-via-kafka" tabindex="-1"><a class="header-anchor" href="#async-flush-via-kafka"><span>Async Flush via Kafka</span></a></h2><p>FluxaORM uses Kafka as the transport for asynchronous SQL flushing. When you call <code>RegisterAsyncFlush()</code> on the registry, FluxaORM registers the internal Kafka topic <code>_fluxa_async_sql</code> (and a dead-letter topic <code>_fluxa_async_sql_failed</code>) on the specified Kafka pool.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterKafka</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">{</span><span class="token string">&quot;localhost:9092&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span></span>
<span class="line">registry<span class="token punctuation">.</span><span class="token function">RegisterAsyncFlush</span><span class="token punctuation">(</span><span class="token string">&quot;events&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>fluxaorm<span class="token punctuation">.</span>AsyncFlushOptions<span class="token punctuation">{</span></span>
<span class="line">    TopicPartitions<span class="token punctuation">:</span> <span class="token number">6</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>When <code>ctx.FlushAsync(true)</code> or <code>ctx.FlushAsync(false)</code> is called, SQL operations are produced to the <code>_fluxa_async_sql</code> topic with the entity table name as the record key. This ensures that queries for the same table are routed to the same partition, preserving per-table ordering.</p><p>The <code>AsyncSQLConsumer</code> uses a Kafka consumer group internally, enabling horizontal scaling across multiple consumer instances. See the <a href="/guide/async_flush">Async Flush</a> page for full details on consuming, error handling, and cache update behavior.</p><p>The topic names are available as constants:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">fluxaorm<span class="token punctuation">.</span>AsyncSQLTopicName           <span class="token comment">// &quot;_fluxa_async_sql&quot;</span></span>
<span class="line">fluxaorm<span class="token punctuation">.</span>AsyncSQLDeadLetterTopicName <span class="token comment">// &quot;_fluxa_async_sql_failed&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>When using <code>GetKafkaAlters()</code>, the async flush topics and consumer group are included automatically if <code>RegisterAsyncFlush()</code> has been called. No manual topic registration is needed for async flush.</p></div><h2 id="closing" tabindex="-1"><a class="header-anchor" href="#closing"><span>Closing</span></a></h2><p>The pool and consumer groups have separate lifecycles and must be closed independently.</p><h3 id="closing-consumer-groups" tabindex="-1"><a class="header-anchor" href="#closing-consumer-groups"><span>Closing Consumer Groups</span></a></h3><p>Each call to <code>ConsumerGroup</code> or <code>MustConsumerGroup</code> creates a new <code>kgo.Client</code>. The caller is responsible for closing it when done:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">cg <span class="token operator">:=</span> pool<span class="token punctuation">.</span><span class="token function">MustConsumerGroup</span><span class="token punctuation">(</span><span class="token string">&quot;my-group&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> cg<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// ... consume records ...</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="closing-the-pool" tabindex="-1"><a class="header-anchor" href="#closing-the-pool"><span>Closing the Pool</span></a></h3><p>Calling <code>Close</code> on the pool closes only the pool-level producer client. It does <strong>not</strong> close any consumer groups — those must be closed individually by the caller:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">pool<span class="token punctuation">.</span><span class="token function">Close</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Tips</p><p>If you are using FluxaORM&#39;s engine lifecycle, the engine will close all Kafka pools when it shuts down. However, consumer groups you created must still be closed by your own code.</p></div>`,68))])}const g=p(r,[["render",d]]),v=JSON.parse('{"path":"/guide/kafka.html","title":"Kafka","lang":"en-US","frontmatter":{},"git":{"updatedTime":1774352294000,"contributors":[{"name":"Lukasz Lato","username":"","email":"latolukasz@gmail.com","commits":6}],"changelog":[{"hash":"09feeb6c2074ac093676ce2f532b0d9bb0dd3f97","time":1774352294000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"debezium"},{"hash":"e0139fa53ed5a09f5dce51534b4d7dd75dd6d84f","time":1773935360000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"},{"hash":"a22380e1eb992caf36fb7f599e3a031c6344b9fa","time":1773928879000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"},{"hash":"4852b4a4972824e1673977c36c7c02f9e918a8d0","time":1773913752000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"},{"hash":"8a796f89e47a3aac8c10635729725af1139d6f3f","time":1773844236000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"},{"hash":"637451bade66fd4bb54ab6a9f2a224e4f444cd65","time":1773756357000,"email":"latolukasz@gmail.com","author":"Lukasz Lato","message":"clickhouse"}]},"filePathRelative":"guide/kafka.md"}');export{g as comp,v as data};
